/* Типы планет, которые есть в системе.

   В списке «Планета» показывается тип, а не имя планеты: товары PI
   зависят от типа и системы, и в системе типа может быть несколько
   планет. Поэтому здесь только множество типов, без повторов.

   Одна строка — одна система, значение — буквы типов через запятую,
   в порядке PLANET_RESOURCES, чтобы список был одинаковым от системы
   к системе. Расшифровка букв — в PLANET_TYPE_CODES.

   Типы, которых нет в PLANET_RESOURCES (Shattered, Scorched Barren),
   перечислены здесь же: планеты с такими типами в SDE есть, но товаров
   PI у них нет, и ячейки P0 и P1 останутся пустыми.

   Типы взяты из sde/universe — из файла solarsystem.yaml каждой системы.
   8035 систем с планетами, 67961 планета, 201 система пустая
   (червоточины, космос Абенниса, без планет), 255 систем
   (Zarzakh, Manifest, Fortitude и другие витринные) в этом зеркале SDE
   отсутствуют — для них список пуст. */
const PLANET_TYPE_CODES = {
    B: 'Barren',
    G: 'Gas',
    I: 'Ice',
    L: 'Lava',
    O: 'Oceanic',
    P: 'Plasma',
    S: 'Storm',
    T: 'Temperate',
    H: 'Shattered',
    C: 'Scorched Barren'
};

